kIn = input(7, "K Neighbors", 1, 20, 1)
featLen = input(20, "Feature Lookback", 5, 40, 1)
mThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
gThresh = input(0.65, "Disagreement Threshold", 0.1, 1.0, 0.01)
showLabels = input(true, "Show Labels")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

warmup = bar_index >= featLen * 2 + 1

bestDist = array()
bestTarg = array()
ii = 0
while ii < kIn {
    array.push(bestDist, 999999.0)
    array.push(bestTarg, 0)
    ii := ii + 1
}

i = 1
while i <= featLen {
    sumSq = 0.0
    j = 0
    while j < featLen {
        cA0 = close[j]
        cB0 = close[j + 1]
        d0 = cB0
        if d0 == 0 { d0 := 0.000000001 }
        f0 = (cA0 - cB0) / d0
        cA1 = close[i + j]
        cB1 = close[i + j + 1]
        d1 = cB1
        if d1 == 0 { d1 := 0.000000001 }
        f1 = (cA1 - cB1) / d1
        diff = f0 - f1
        sumSq := sumSq + diff * diff
        j := j + 1
    }
    dist = sqrt(sumSq)
    vi = -1
    if close[i - 1] > close[i] { vi := 1 }
    insertIdx = -1
    m = 0
    while m < kIn {
        if dist < bestDist[m] {
            insertIdx := m
            m := kIn
        }
        m := m + 1
    }
    if insertIdx >= 0 {
        m = kIn - 1
        while m > insertIdx {
            array.set(bestDist, m, bestDist[m - 1])
            array.set(bestTarg, m, bestTarg[m - 1])
            m := m - 1
        }
        array.set(bestDist, insertIdx, dist)
        array.set(bestTarg, insertIdx, vi)
    }
    i := i + 1
}

bullCount = 0
bearCount = 0
m2 = 0
while m2 < kIn {
    if bestDist[m2] < 999999.0 {
        if bestTarg[m2] == 1 { bullCount := bullCount + 1 }
        else { bearCount := bearCount + 1 }
    }
    m2 := m2 + 1
}

kF = kIn * 1.0
margin = 0.0
disagree = 0.0
if warmup {
    margin := (bullCount - bearCount) / kF
    p = bullCount / kF
    disagree := 4.0 * p * (1.0 - p)
}

prismH = abs(margin)
prismCol = "#ff4477"
if margin > 0 { prismCol := "#22cc88" }

buyCond = warmup and margin > mThresh and disagree < gThresh
sellCond = warmup and margin < 0 - mThresh and disagree < gThresh
buyPrev = buyCond[1]
sellPrev = sellCond[1]
buySig = buyCond and not buyPrev
sellSig = sellCond and not sellPrev

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

plot(margin, "Vote Margin M", "#22cc88", 2, "separate")
plot(disagree, "Disagreement G", "#ffd43b", 1, "separate")
hline(0, "#888888", "separate")
hline(0.65, "#ffd43b", "separate")

plot3d(prismH, "Prism Height |M|", "bars3d", prismCol, "separate")
plot3d(disagree, "Prism Width G", "ribbon", "#ffd43b", "separate", 1)

if buySig { plotshape_3d(bar_index, low, "Buy", "diamond", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "diamond", "#ff4477", 1.0 * markerSize, 0, "separate") }
if showLabels and buySig { label3d(bar_index, low, "Buy", "#22cc88", 1, 0, "separate") }
if showLabels and sellSig { label3d(bar_index, high, "Sell", "#ff4477", 1, 0, "separate") }

numRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(120, "Session Length (bars visible)", 30, 300, 10)
showVA = input(true, "Show Value Area")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
if rng <= 0 {
    rng := 1.0
}

binVol = array()
i = 0
while i < numRows {
    array.push(binVol, 0.0)
    i := i + 1
}

totalVol = 0.0
k = 0
while k < sessLen {
    bh = high[k]
    bl = low[k]
    bv = volume[k]
    bRange = bh - bl
    if bv < 0 {
        bv := 0.0
    }
    totalVol := totalVol + bv
    if bRange <= 0 {
        ci = floor((close[k] - ll) / rng * numRows)
        if ci < 0 {
            ci := 0
        }
        if ci > numRows - 1 {
            ci := numRows - 1
        }
        array.set(binVol, ci, array.get(binVol, ci) + bv)
    } else {
        b = 0
        while b < numRows {
            binTop = ll + (b + 1) / numRows * rng
            binBot = ll + b / numRows * rng
            top = bh
            if binTop < top {
                top := binTop
            }
            bot = bl
            if binBot > bot {
                bot := binBot
            }
            ov = top - bot
            if ov > 0 {
                share = ov / bRange
                array.set(binVol, b, array.get(binVol, b) + bv * share)
            }
            b := b + 1
        }
    }
    k := k + 1
}

profTotal = array.sum(binVol)
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < numRows {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) / numRows * rng
pocShare = 0.0
if profTotal > 0 {
    pocShare := pocVal / profTotal
}

vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = profTotal * vaPct / 100
guard = 0
while accum < target and guard < numRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < numRows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < numRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < numRows - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vaHighPrice = ll + (vaHigh + 1) / numRows * rng
vaLowPrice = ll + vaLow / numRows * rng
vaMid = (vaHighPrice + vaLowPrice) / 2
terrainTop = vaMid + (pocShare - 0.5) * rng + (profTotal / sessLen) / (profTotal / sessLen + 1.0) * 0.0
terrainTop := vaLowPrice + pocShare * (vaHighPrice - vaLowPrice) + (close - vaMid) * 0.0 + (vaHighPrice - vaLowPrice) * 0.5
terrainTop := vaMid + (pocShare * 2 - 1.0) * (vaHighPrice - vaLowPrice) * 0.5
terrainLine = vaMid + (pocPrice - vaMid) * 0.5

prevClose = close[1]
prevInside = prevClose >= vaLowPrice and prevClose <= vaHighPrice
buySig = prevInside and close > vaHighPrice and volume > 0
sellSig = prevInside and close < vaLowPrice and volume > 0

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vaHighPrice, "VAH", "#22cc88", 1, "stepline")
plot(vaLowPrice, "VAL", "#ff4477", 1, "stepline")
plot(terrainLine, "Value Terrain Twin", "#4488ff", 1)

box.new(bar_index - sessLen, vaHighPrice, bar_index, vaLowPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "vaBox")
text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "pocLbl")

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}

plot3d(terrainLine, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vaHighPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")

if showVA {
    bgcolor("rgba(34,204,136,0.04)")
}

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain lvl recomputed every bar.
// Fix 2: close[-1] peeked one bar into the future — changed to close > lvl (no lookahead).
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine signature — changed to OakScript positional (bar_index, price, title, style, color) with quoted strings.
// Fix 4: RSI surface forced into pane "3d" renders as spiky forest over candles — moved to pane "separate" per PANE LAW.
lenH = input(20, "High Length", 1, 100, 1)
lenR = input(14, "RSI Length", 2, 50, 1)
osLevel = input(30, "Oversold Level", 1, 50, 1)

lvl = highest(high, lenH)
r = rsi(close, lenR)

buySig = close > lvl
osSig = crossover(r, osLevel)

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}

plot(r, "RSI", "#b48cff", 1, "line", "separate")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

xIn = input(1.0, "Wind Dir X", -5.0, 5.0, 0.1)
yIn = input(0.0, "Wind Dir Y", -5.0, 5.0, 0.1)
zIn = input(0.0, "Wind Dir Z", -5.0, 5.0, 0.1)
windSpeedIn = input(10.0, "Wind Speed Knots", 0.0, 100.0, 0.5)
minSpeed = input(0.0, "Min Speed Knots", 0.0, 50.0, 0.5)
maxSpeed = input(50.0, "Max Speed Knots", 10.0, 100.0, 0.5)
baseTail = input(1.0, "Base Tail Length", 0.2, 3.0, 0.1)
lenPerKnot = input(0.1, "Length Per Knot", 0.0, 0.5, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

drift = close - open
xEff = xIn + drift * 0.01
yEff = yIn + drift * 0.007
zEff = zIn + (high - low) * 0.01
speedEff = windSpeedIn + drift * 0.05

mag = sqrt(xEff * xEff + yEff * yEff + zEff * zEff + 0.000000001)
nx = xEff / mag
ny = yEff / mag
nz = zEff / mag
horiz = sqrt(nx * nx + ny * ny + 0.000000001)

rYaw = ny / (nx + 0.000000001)
aYaw = abs(rYaw)
invYaw = 1.0 / (rYaw + 0.000000001)
atanInvYaw = invYaw / (1.0 + 0.28 * invYaw * invYaw)
atanSmallYaw = rYaw / (1.0 + 0.28 * rYaw * rYaw)
atanRadYaw = atanSmallYaw
if aYaw > 1.0 {
  atanRadYaw = 1.5707963 - atanInvYaw
}
if rYaw < 0.0 and aYaw > 1.0 {
  atanRadYaw = -1.5707963 - atanInvYaw
}
atanDegYaw = atanRadYaw * 57.29578
yaw = atanDegYaw
if nx < 0.0 and ny >= 0.0 {
  yaw = 180.0 + atanDegYaw
}
if nx < 0.0 and ny < 0.0 {
  yaw = -180.0 + atanDegYaw
}
if nx == 0.0 and ny > 0.0 {
  yaw = 90.0
}
if nx == 0.0 and ny < 0.0 {
  yaw = -90.0
}

rPitch = nz / (horiz + 0.000000001)
aPitch = abs(rPitch)
invPitch = 1.0 / (rPitch + 0.000000001)
atanInvPitch = invPitch / (1.0 + 0.28 * invPitch * invPitch)
atanSmallPitch = rPitch / (1.0 + 0.28 * rPitch * rPitch)
atanRadPitch = atanSmallPitch
if aPitch > 1.0 {
  atanRadPitch = 1.5707963 - atanInvPitch
}
if rPitch < 0.0 and aPitch > 1.0 {
  atanRadPitch = -1.5707963 - atanInvPitch
}
pitch = atanRadPitch * 57.29578
roll = 0.0

tailLen = baseTail + speedEff * lenPerKnot
span = maxSpeed - minSpeed + 0.000000001
tRaw = (speedEff - minSpeed) / span
tRatio = tRaw
if tRaw < 0.0 {
  tRatio = 0.0
}
if tRaw > 1.0 {
  tRatio = 1.0
}
rComp = tRatio * 1.0
gComp = tRatio * 0.5
bComp = 1.0 - tRatio * 1.0

strongLvl = maxSpeed * 0.7
weakLvl = minSpeed + span * 0.2
buySig = crossover(speedEff, strongLvl)
sellSig = crossunder(speedEff, weakLvl)

yawPrev = yaw[1]
pitchPrev = pitch[1]
yawDiffRaw = abs(yaw - yawPrev)
yawDiff = yawDiffRaw
if yawDiffRaw > 180.0 {
  yawDiff = 360.0 - yawDiffRaw
}
pitchDiff = abs(pitch - pitchPrev)
shiftCond = (yawDiff > 30.0 or pitchDiff > 20.0) and speedEff > minSpeed
shiftSig = shiftCond and not shiftCond[1]

arrowColor = "#3388ff"
if tRatio > 0.33 {
  arrowColor = "#7a8fd4"
}
if tRatio > 0.66 {
  arrowColor = "#ff8800"
}

originState = bar_index == 0
originSig = originState and not originState[1]

coneSize = tailLen * markerSize
if coneSize < 0.2 {
  coneSize = 0.2
}
if coneSize > 3.0 {
  coneSize = 3.0
}

if buySig {
  plotshape(bar_index, low, "Strong Flow", "triangleup", "#ff8800")
}
if sellSig {
  plotshape(bar_index, high, "Flow Collapse", "triangledown", "#3388ff")
}
if shiftSig {
  plotshape(bar_index, high, "Shift", "diamond", "#ff8800")
}
if originSig {
  plotshape(bar_index, low, "Origin", "diamond", "#3388ff")
}

plot(speedEff, "Wind Speed kn", "#3388ff", 2, "separate")
plot(tailLen, "Tail Length", "#ff8800", 1, "separate")
plot(yaw, "Yaw deg", "#22cc88", 1, "separate")
plot3d(speedEff, "Wind Speed 3D", "ribbon", "#3388ff", "separate")
plot3d(tailLen, "Tail Length 3D", "line3d", "#ff8800", "separate", 1)
plot3d(yaw, "Yaw 3D", "trail", "#22cc88", "separate", 2)
if originSig {
  plotshape_3d(bar_index, low, "Origin", "sphere", "#3388ff", 0.5, 0, "separate", 0, 0, 0)
}
if buySig {
  plotshape_3d(bar_index, low, "Strong Flow", "coneup", "#ff8800", coneSize, 1, "separate", pitch, yaw, roll)
}
if sellSig {
  plotshape_3d(bar_index, high, "Collapse", "conedown", "#3388ff", coneSize, 1, "separate", pitch, yaw, roll)
}
if shiftSig {
  plotshape_3d(bar_index, high, "Shift", "diamond", "#ffcc00", coneSize, 2, "separate", pitch, yaw, roll)
}
if buySig {
  label3d(bar_index, low, "GUST", "#ff8800", 1, 1, "separate")
}
